import { relations } from "drizzle-orm"
import {
	bigint,
	index,
	pgTable,
	text,
	timestamp,
	uniqueIndex,
} from "drizzle-orm/pg-core"
import { organization, user } from "./auth.js"

/**
 * Application-owned organization state (RFC-001 §5, §10 "Application
 * schema ownership"). These tables are NOT generated by the
 * better-auth `auth:generate` command — they are hand-written here
 * and exported from `packages/database/src/schema/index.ts` so the
 * Drizzle `db:generate` diff picks them up.
 *
 * Keep these tables out of the auto-generated `auth.ts` so the
 * next `auth:generate` run does not clobber them. The barrel
 * `index.ts` re-exports them.
 */

/**
 * Durable record of the account's permanent default organization
 * (RFC-001 §5 "Permanent default organization invariant"). One row
 * per account. The `userId` is the primary key (one default per
 * account). The `organizationId` is a non-null foreign key with
 * `ON DELETE RESTRICT`: deleting the organization is rejected at
 * the database level by the application invariant.
 *
 * The account cannot edit, replace, or clear this row through
 * profile/metadata APIs; only the durable provisioning protocol
 * writes it (during the finalization step in
 * `createFirstOrganization`).
 */
export const accountOrganizationDefaults = pgTable(
	"account_organization_defaults",
	{
		userId: text("user_id")
			.primaryKey()
			.references(() => user.id, { onDelete: "cascade" }),
		organizationId: text("organization_id")
			.notNull()
			.references(() => organization.id, { onDelete: "restrict" }),
		createdAt: timestamp("created_at").defaultNow().notNull(),
	},
	(table) => [
		uniqueIndex("account_org_defaults_org_uidx").on(table.organizationId),
	],
)

/**
 * Durable onboarding provisioning record (RFC-001 §5 "First-organization
 * provisioning", option B). One row per account. The status
 * transitions: `pending` → `completed`. The `leaseUntil` and
 * `fencingToken` implement the recovery protocol: only the worker
 * holding the current fencing token can mutate the row; an
 * expired lease allows recovery, not an unconditional new
 * creation.
 *
 * `operationId` is a server-generated unique identifier the
 * plugin carries through native creation (as the
 * `bootstrapOperationId` additional field on the `organization`
 * row). Database uniqueness on the plugin-side marker prevents a
 * second organization if an earlier worker resumes late.
 *
 * The `requestedName` and `finalSlug` are persisted for retry
 * consistency. The `organizationId` is nullable while
 * `status = 'pending'`; it is set when the native organization
 * row is created.
 */
export const accountOrganizationProvisioning = pgTable(
	"account_organization_provisioning",
	{
		userId: text("user_id")
			.primaryKey()
			.references(() => user.id, { onDelete: "cascade" }),
		operationId: text("operation_id").notNull(),
		organizationId: text("organization_id").references(() => organization.id, {
			onDelete: "set null",
		}),
		status: text("status").notNull().default("pending"),
		// `requestedName` and `finalSlug` capture the user-submitted
		// input and the server-resolved slug for idempotent retries.
		requestedName: text("requested_name").notNull(),
		finalSlug: text("final_slug").notNull(),
		// Lease proposal is 60s; renewals require the current fencing
		// token. Stored as a Unix timestamp (milliseconds) so the
		// comparison is `now() < leaseUntil` against the database
		// clock; we never hold a transaction across a native auth
		// call.
		leaseUntil: bigint("lease_until", { mode: "number" }).notNull(),
		// Monotonically increasing token. Conditional updates use
		// `WHERE fencing_token = <expected>` so a stale worker cannot
		// overwrite a newer state.
		fencingToken: bigint("fencing_token", { mode: "number" })
			.notNull()
			.default(1),
		createdAt: timestamp("created_at").defaultNow().notNull(),
		updatedAt: timestamp("updated_at")
			.defaultNow()
			.$onUpdate(() => new Date())
			.notNull(),
	},
	(table) => [
		uniqueIndex("account_org_provisioning_op_uidx").on(table.operationId),
		index("account_org_provisioning_status_idx").on(table.status),
		index("account_org_provisioning_lease_idx").on(table.leaseUntil),
	],
)

/**
 * Relations. Used by Drizzle's `with: { user: true }` query helper.
 * `accountOrganizationDefaults.user` and `.organization` resolve
 * the account and the permanent default. The provisioning table
 * mirrors the same shape.
 */
export const accountOrganizationDefaultsRelations = relations(
	accountOrganizationDefaults,
	({ one }) => ({
		user: one(user, {
			fields: [accountOrganizationDefaults.userId],
			references: [user.id],
		}),
		organization: one(organization, {
			fields: [accountOrganizationDefaults.organizationId],
			references: [organization.id],
		}),
	}),
)

export const accountOrganizationProvisioningRelations = relations(
	accountOrganizationProvisioning,
	({ one }) => ({
		user: one(user, {
			fields: [accountOrganizationProvisioning.userId],
			references: [user.id],
		}),
		organization: one(organization, {
			fields: [accountOrganizationProvisioning.organizationId],
			references: [organization.id],
		}),
	}),
)
